CREATE TABLE IF NOT EXISTS users (
 id text PRIMARY KEY DEFAULT gen_random_uuid()::text, email text NOT NULL UNIQUE,
 password_hash text NOT NULL, name text NOT NULL, avatar text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '',
 verified boolean NOT NULL DEFAULT false, provider_status text NOT NULL DEFAULT 'none' CHECK(provider_status IN ('none','pending','approved','rejected')),
 role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), active boolean NOT NULL DEFAULT true,
 tags jsonb NOT NULL DEFAULT '[]', city_ids text[] NOT NULL DEFAULT '{}', quote text NOT NULL DEFAULT '', social_links jsonb NOT NULL DEFAULT '[]',
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), refresh_hash text NOT NULL, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS email_tokens (hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('verify','reset')),expires_at timestamptz NOT NULL,consumed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS places (id text PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('country','city','attraction')),parent_id text REFERENCES places(id),country text NOT NULL,name jsonb NOT NULL,lat double precision NOT NULL,lng double precision NOT NULL,description jsonb NOT NULL DEFAULT '{}',image text NOT NULL DEFAULT '',aliases text[] NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS places_parent ON places(parent_id);
CREATE TABLE IF NOT EXISTS favorites (user_id text REFERENCES users(id),city_id text REFERENCES places(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,city_id));
CREATE TABLE IF NOT EXISTS profile_drafts(user_id text PRIMARY KEY REFERENCES users(id),revision integer NOT NULL DEFAULT 1,layout jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profile_publications(user_id text PRIMARY KEY REFERENCES users(id),revision integer NOT NULL,layout jsonb NOT NULL,published_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profile_history(user_id text REFERENCES users(id),revision integer NOT NULL,layout jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,revision));
CREATE TABLE IF NOT EXISTS layout_jobs(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','validating','ready','failed','cancelled')),base_revision integer NOT NULL,base_layout jsonb NOT NULL,prompt text NOT NULL,layout jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_layout_job ON layout_jobs(user_id) WHERE status IN ('queued','running','validating');
CREATE TABLE IF NOT EXISTS packages(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL,city_ids text[] NOT NULL DEFAULT '{}',price text NOT NULL DEFAULT '',currency text NOT NULL DEFAULT 'USD',unit text NOT NULL DEFAULT 'day',image text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS packages_user ON packages(user_id,status);
CREATE TABLE IF NOT EXISTS files(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),storage_key text NOT NULL,mime text NOT NULL,size integer NOT NULL,purpose text NOT NULL CHECK(purpose IN ('public','chat','verification')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verifications(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('professional','experience')),name text NOT NULL,description text NOT NULL,file_ids text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending',reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE TABLE IF NOT EXISTS posts(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users(id),city_id text NOT NULL REFERENCES places(id),title text NOT NULL,body text NOT NULL,images jsonb NOT NULL DEFAULT '[]',hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS posts_feed ON posts(created_at DESC,id);
CREATE TABLE IF NOT EXISTS post_likes(post_id text REFERENCES posts(id),user_id text REFERENCES users(id),PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS comments(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,post_id text NOT NULL REFERENCES posts(id),user_id text NOT NULL REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS blocks(user_id text REFERENCES users(id),blocked_id text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,blocked_id),CHECK(user_id<>blocked_id));
CREATE TABLE IF NOT EXISTS conversations(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_a text NOT NULL REFERENCES users(id),user_b text NOT NULL REFERENCES users(id),city_id text REFERENCES places(id),last_sequence integer NOT NULL DEFAULT 0,last_message text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_a,user_b),CHECK(user_a<user_b));
CREATE INDEX IF NOT EXISTS conversations_a ON conversations(user_a,updated_at DESC);
CREATE INDEX IF NOT EXISTS conversations_b ON conversations(user_b,updated_at DESC);
CREATE TABLE IF NOT EXISTS messages(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,conversation_id text NOT NULL REFERENCES conversations(id),sender_id text NOT NULL REFERENCES users(id),client_message_id text NOT NULL,sequence integer NOT NULL,type text NOT NULL CHECK(type IN ('text','image','contact','place','package','trip')),body text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,sequence),UNIQUE(sender_id,client_message_id));
CREATE INDEX IF NOT EXISTS messages_history ON messages(conversation_id,sequence DESC);
CREATE TABLE IF NOT EXISTS read_positions(conversation_id text REFERENCES conversations(id),user_id text REFERENCES users(id),sequence integer NOT NULL DEFAULT 0,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS trips(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,conversation_id text NOT NULL REFERENCES conversations(id),creator_id text NOT NULL REFERENCES users(id),peer_id text NOT NULL REFERENCES users(id),city_id text NOT NULL REFERENCES places(id),title text NOT NULL,end_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','active','reviewable','cancelled')),frozen boolean NOT NULL DEFAULT false,confirmations text[] NOT NULL DEFAULT '{}',opened_by text CHECK(opened_by IN ('scheduled','mutual','admin')),accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS trips_due ON trips(end_at) WHERE status='active';
CREATE TABLE IF NOT EXISTS reviews(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,trip_id text NOT NULL REFERENCES trips(id),author_id text NOT NULL REFERENCES users(id),target_id text NOT NULL REFERENCES users(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body text NOT NULL,hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(trip_id,author_id));
CREATE TABLE IF NOT EXISTS reports(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,reporter_id text NOT NULL REFERENCES users(id),target_type text NOT NULL CHECK(target_type IN ('user','post','message','review','trip')),target_id text NOT NULL,reason text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'open',resolution text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,actor_id text NOT NULL REFERENCES users(id),action text NOT NULL,target_id text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_ids text[] NOT NULL,event text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(created_at) WHERE delivered_at IS NULL;
